mapper.select:
select c.cust_id, c.cust_cd, c.cust_nm, s.trade_status
  from mst_cust c left join srm_supplier s on s.cust_id = c.cust_id
 where c.cust_id = #{custId}

select 
  from srm_asn a left join sys_plant pl on pl.plant_cd = a.plant_cd
 where a.asn_id = #{asnId} and a.cust_id = #{custId}

select 
  from srm_claim k
 where k.cust_id = #{custId} and k.sent_at is not null
   and k.sent_at >= (#{from}::date)::timestamp at time zone #{zone}
   and k.sent_at < (#{to}::date + 1)::timestamp at time zone #{zone}
and k.status = #{status}
 order by k.sent_at desc, k.claim_id desc
 limit 500
